"""Freeze 45 NEW questions, dev/test split by source document before retrieval."""
import json
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT))
from starter.src.corpus import load_multidoc_pages
pages=load_multidoc_pages(ROOT)
lookup={(p['document_id'],p['page']):p for p in pages}
items=[]
def add(doc,page,question,answer,evidence,kind='paraphrase',filters=None):
 if evidence not in lookup[doc,page]['text']:raise ValueError(f'Evidence absent: {doc}/{page}: {evidence}')
 # Accept exact equivalent evidence wherever it really occurs in the indexed corpus.
 alternatives=[dict(source_id=p['document_id'],page=p['page'],evidence_quote=evidence) for p in pages if (p['document_id'],p['page'])!=(doc,page) and evidence in p['text']]
 prefix={'nd69':'m69','nd42':'m42','sherlock':'msh'}[doc];n=sum(q['gold_source_id']==doc for q in items)+1
 items.append(dict(id=f'{prefix}{n:02}',split='dev' if doc=='nd69' else 'test',question=question,expected_answer=answer,
  gold_source_id=doc,gold_page=page,evidence_quote=evidence,filter=filters or {},alternatives=alternatives,kind=kind,
  note='Source-authored before retrieval; reviewed by source review. No claim of independent human labels. Legal questions refer to the downloaded historical snapshot.'))
